suppressPackageStartupMessages({ library(readxl); library(dplyr) })
T <- "C:/Users/bhadury/University of Michigan Dropbox/Sagnik Bhadury/CODES/SBTurboCodes/entropy/Research - DOE Horseshoe/TRIDENT"
options(width = 230, digits = 4)
emb2code <- c("UNI V2" = "uni_v2", "VIRCHOW" = "virchow2", "H-OPTIMUS 1" = "hoptimus1", "CONCH V1.5" = "conch_v15")
g <- as.data.frame(read_excel(file.path(T, "mi summary table.xlsx"))); g$code <- emb2code[g$Embeddings]
best <- as.data.frame(read_excel(file.path(T, "best kpca summary.xlsx"))); best$code <- emb2code[best$Embeddings]
inc <- as.data.frame(read_excel(file.path(T, "incremental mi summary.xlsx"))); inc$code <- emb2code[inc$Embeddings]
u <- read.csv(file.path(T, "usable", "usable_infold.csv"))
cat("\n#### reproducibility identities (vision-only = not CONCH)\n")
j <- merge(inc, best[, c("Disease", "target", "code", "agg_method", "MI_obs")], by = c("Disease", "target", "code", "agg_method"))
id1 <- data.frame(src = "replicate refit", code = j$code, d = j$emb_only - j$MI_obs)
id2 <- data.frame(src = "null covariate", code = inc$code[inc$covar_only == 0], d = (inc$combined - inc$emb_only)[inc$covar_only == 0])
uu <- u[!u$control, ]; uu$code <- sub("\\|.*", "", sub("^[A-Z]+\\|", "", uu$id))
id3 <- data.frame(src = "sign flip refit", code = uu$code, d = uu$MI_refit - uu$MI_obs)
ids <- rbind(id1, id2, id3)
print(ids %>% group_by(src) %>% summarise(n = n(), exact = sum(abs(d) < 1e-9), max_vis = max(abs(d[code != "conch_v15"])), max_all = max(abs(d)), q95_vis = quantile(abs(d[code != "conch_v15"]), .95)))
cat("largest discrepancies:\n"); print(head(ids[order(-abs(ids$d)), ], 8))
cat("\n#### chain seeds and size prior\n"); cs <- read.csv(file.path(T, "robustness", "chain_sizeprior.csv"))
print(cs %>% filter(what == "seed") %>% group_by(id) %>% summarise(MI_table = first(MI_table), lo = min(MI), hi = max(MI), range = hi - lo))
print(cs %>% filter(what == "sizeprior") %>% transmute(id, MI_table, MI, ratio = MI / MI_table, k))
cat("\n#### dimension sweep\n"); dm <- read.csv(file.path(T, "robustness", "dimension_sweep.csv")); print(dm[, c("id", "role", "d", "MI", "k", "null_mean", "p_perm", "eig_cond")])
cat("\n#### vbeta sweep\n"); vb <- read.csv(file.path(T, "robustness", "vbeta_sweep.csv")); print(vb[, intersect(names(vb), c("id", "role", "v_beta", "MI", "k", "null_mean", "p_perm"))])
cat("\n#### bootstrap with replacement (bias)\n"); bs <- read.csv(file.path(T, "robustness", "bootstrap_summary.csv")); b <- bs$boot_mean - bs$MI_obs
cat(sprintf("57 arms: median %+.4f range %+.4f to %+.4f negative %d | k_hi max %s\n", median(b), min(b), max(b), sum(b < 0), max(bs$k_hi)))
ss <- read.csv(file.path(T, "robustness", "subsampling_summary.csv")); cat(sprintf("half-sampling s.e.: 57 arms %.4f-%.4f median %.4f | selected median %.4f\n", min(ss$se_n), max(ss$se_n), median(ss$se_n), median(ss$se_n[grepl("selected", ss$arm)])))
cat("\n#### Record\n"); rec <- read.csv(file.path(T, "record", "recoverability_record.csv"))
print(rec[, c("state", "model", "n", "H_Y", "I_hat", "share", "null_mean", "eps_rep", "se_n", "ci90_lo", "ci90_hi", "threshold", "status", "N_evidence", "I_adjusted", "I_usable", "auc_oof", "I_usable_pathmi", "N90", "N95", "projection", "pooling")])
cat("\n#### learning curves\n"); lc <- read.csv(file.path(T, "learning", "learning_summary.csv"))
print(lc[lc$n %in% c(50, 100, 150, 200) | lc$source == "full cohort", c("id", "n", "I_mean", "se", "null_mean", "threshold", "LCB", "resolved", "U_mean", "k_star")])
cat("\n#### usable stats\n"); cat(readLines(file.path(T, "usable", "usable_infold_stats.txt")), sep = "\n")
cat("\n#### PRAD extended covariates\n"); pe <- read.csv(file.path(T, "prad_incremental_batch_purity", "prad_incremental_batch_purity.csv")); print(pe[, c("model", "target", "pooling", "covar_C0_refit", "covar_purity", "covar_batch", "covar_all", "emb_only", "combined_all", "incremental_all")])
co <- read.csv(file.path(T, "prad_incremental_batch_purity", "covariate_only_fits.csv")); print(co[co$covariate_set != "C0", c("model", "target", "covariate_set", "MI", "selected")])
cat("\n#### burden\n"); nq <- read.csv(file.path(T, "burden", "burden_Nq_bootstrap.csv")); print(nq)
cat(readLines(file.path(T, "burden", "burden_ordering_summary.txt")), sep = "\n")
cat("\n#### tile fits\n"); for (co in c("crc", "prad")) print(read.csv(file.path(T, "tile_maps_hoptimus1", co, sprintf("fit_summary_%s_hoptimus1.csv", co)))[, c("target", "n", "prevalence", "k_star", "MI_subho", "MI_plugin", "MI_plugin_lo90", "MI_plugin_hi90", "mean_eta_sd", "auc")])
